static void require(bool b,const char* m){if(!b)throw std::runtime_error(m);}
static void supplies(Construction* c){c->commodityCount[STUFF_LABOR]=1000;c->commodityCount[STUFF_GOODS]=1000;}
static int id(World& w,MapPoint p){return p.y*w.map.len()+p.x;}
static auto city(){auto w=new_barren_city(50);w->total_money=10000000;w->tech_level=MAX_TECH_LEVEL;return w;}
int main(int argc,char** argv){try{
 initializeModules();
 if(argc>1){auto w=new_barren_city(60);w->total_money=10000000;w->tech_level=MAX_TECH_LEVEL;w->evolution.cityName="Preview 13 art review";w->evolution.skyPhase=2;w->evolution.skyDuration=960000;w->evolution.skyElapsed=50000;
 for(int x=3;x<55;++x)w->buildConstruction(roadConstructionGroup,{x,28});
 ConstructionGroup* towers[]={&ivoryTowerGroup,&brickTowerGroup,&sandTowerGroup,&glassOfficeGroup,&bronzeOfficeGroup,&decoOfficeGroup};for(int i=0;i<6;++i){MapPoint p(6+i*7,25);w->buildConstruction(*towers[i],p);auto* c=w->map(p)->construction;supplies(c);c->commodityCount[STUFF_LOVOLT]=1000;c->flags|=FLAG_HAD_POWER;if(i<3)static_cast<Residence*>(c)->local_population=200;}
 w->buildConstruction(policeGroup,{12,29});w->buildConstruction(fireStationConstructionGroup,{16,29});w->buildConstruction(healthCentreConstructionGroup,{20,29});w->buildConstruction(churchConstructionGroup,{25,29});w->buildConstruction(potteryConstructionGroup,{32,29});for(auto* c:w->map.constructions){if(c->constructionGroup->group==GROUP_POLICE||c->constructionGroup->group==GROUP_FIRESTATION||c->constructionGroup->group==GROUP_HEALTH)supplies(c);}w->save(argv[1]);std::cout<<"PASS review fixture\n";return 0;}
 auto w=city();w->buildConstruction(fireStationConstructionGroup,{5,10});w->buildConstruction(potteryConstructionGroup,{35,10});auto* station=static_cast<FireStation*>(w->map({5,10})->construction);station->active=true;supplies(station);auto* pottery=w->map({35,10})->construction;int target=id(*w,{35,10});
 auto off=w->civic.route(*w,id(*w,{5,10}),target);require(!off.empty(),"off-road response route");int offcost=0;for(int tile:off)offcost+=w->civic.terrainCost(*w,tile,id(*w,{5,10}),target);
 for(int x=5;x<=35;++x)w->buildConstruction(roadConstructionGroup,{x,9});auto road=w->civic.route(*w,id(*w,{5,10}),target);int roadcost=0;for(int tile:road)roadcost+=w->civic.terrainCost(*w,tile,id(*w,{5,10}),target);require(roadcost<offcost,"roads speed response");
 pottery->torch();require(w->map({35,10})->construction==pottery&&w->civic.burningAt(target),"building remains rescueable");for(int day=1;day<=270;++day){w->total_time=day;w->civic.update(*w);}require(w->map({35,10})->construction==pottery&&!w->civic.burningAt(target)&&w->civic.resolved>0,"arrived fire crew saves building");std::cout<<"PASS road/off-road routing and fire rescue\n";
 auto doomed=city();doomed->buildConstruction(potteryConstructionGroup,{20,20});doomed->map({20,20})->construction->torch();for(int d=1;d<=601;++d){doomed->total_time=d;doomed->civic.update(*doomed);}require(doomed->map({20,20})->construction->constructionGroup->group==GROUP_FIRE,"unanswered fire eventually burns down");
 for(int y=1;y<49;++y){if(w->map({25,y})->construction)w->bulldozeArea({25,y});w->map({25,y})->setTerrain(GROUP_WATER);}require(w->civic.route(*w,id(*w,{5,10}),target).empty(),"water cannot be crossed without bridge");
 auto civic=city();civic->buildConstruction(policeGroup,{5,30});civic->buildConstruction(healthCentreConstructionGroup,{10,30});civic->buildConstruction(residenceLLConstructionGroup,{35,30});auto* hospital=static_cast<HealthCentre*>(civic->map({10,30})->construction);hospital->active=true;supplies(hospital);supplies(civic->map({5,30})->construction);auto* home=static_cast<Residence*>(civic->map({35,30})->construction);home->local_population=50;int h=id(*civic,home->point);civic->civic.sick[h]=10;civic->civic.addIncident(CivicServices::MEDICAL_CALL,h,5);civic->civic.addIncident(CivicServices::CRIME_CALL,h,5);civic->total_time=10;civic->civic.update(*civic);bool ambulance=false,police=false;for(auto& u:civic->civic.units){ambulance|=u.kind==CivicServices::MEDICAL_CALL;police|=u.kind==CivicServices::CRIME_CALL;}require(ambulance&&police,"real police and ambulance assignments");
 auto path=std::filesystem::temp_directory_path()/"civic-save-check.scn.gz";civic->save(path);auto loaded=World::load(path);std::filesystem::remove(path);require(civic->civic.save()==loaded->civic.save(),"full save/load preserves state and routes on 50 map");
 auto health=city();health->buildConstruction(residenceHLConstructionGroup,{15,15});auto* residents=static_cast<Residence*>(health->map({15,15})->construction);residents->local_population=150;int hid=id(*health,residents->point);health->map(residents->point)->pollution=3000;for(int i=0;i<12;++i)health->civic.monthly(*health);int sick=health->civic.illAt(hid);require(sick>0,"pollution causes illness");health->map(residents->point)->pollution=0;health->map(residents->point)->flags|=FLAG_HEALTH_COVER;for(int i=0;i<12;++i)health->civic.monthly(*health);require(health->civic.illAt(hid)<sick,"clean air and healthcare recovery");
 health->civic.education=0;health->civic.monthly(*health);int before=health->civic.crime;health->civic.education=1000;health->civic.monthly(*health);require(health->civic.crime<before,"education lowers incident rate");health->civic.autoTax=true;health->money_rates.income_tax=10;health->total_money=0;health->evolution.mayorMode=0;health->civic.monthly(*health);require(health->money_rates.income_tax==10,"mayor OFF does not change tax");health->evolution.mayorMode=1;health->civic.taxCeiling=11;for(int i=0;i<10;++i)health->civic.monthly(*health);require(health->money_rates.income_tax==11,"automatic tax respects ceiling");
 require(health->civic.zombiesEnabled,"Easter egg enabled by default");health->map(residents->point)->pollution=3000;health->total_time=6*NUMOF_DAYS_IN_YEAR;for(int i=0;i<3000&&!health->civic.zombieNoticePending;++i)health->civic.monthly(*health);require(health->civic.zombieNoticePending,"rare event can trigger after persistent extreme pollution");health->civic.zombiesEnabled=false;health->civic.update(*health);for(auto& c:health->civic.incidents)require(c.kind!=CivicServices::ZOMBIE_CALL,"off switch clears outbreak");
 bool rejected=false;try{CivicServices bad;bad.load("1 100 100 100 100",50);}catch(const std::exception&){rejected=true;}require(rejected,"malformed state rejected");
 auto large=new_barren_city(200);large->transit.tunnels.insert(175*200+100);large->transit.viaducts.insert(176*200+101);large->save(path);auto read=World::load(path);std::filesystem::remove(path);require(read->transit.tunnels==large->transit.tunnels&&read->transit.viaducts==large->transit.viaducts,"large map underground layers survive load");
 CivicServices full;for(int i=0;i<64;++i)full.addIncident(CivicServices::MEDICAL_CALL,i,5);require(full.addIncident(CivicServices::FIRE_CALL,100,60)&&full.incidents.size()==64,"critical call replaces ordinary saturated queue");auto state=full.save();full.addIncident(CivicServices::FIRE_CALL,100,60);require(full.save()==state,"duplicate critical call cannot evict another call");
 auto towers=city();towers->buildConstruction(ivoryTowerGroup,{5,5});require(static_cast<Residence*>(towers->map({5,5})->construction)->max_population==600,"tower has capacity and valid registration");
 std::cout<<"PASS police, ambulances, budgets, education, pollution illness, zombies, route saves, large map layers and new towers\n";
}catch(const Message::Exception& e){std::cerr<<e.getMessage()->str()<<'\n';return 1;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
